---@type vana.Mod
---@diagnostic disable-next-line: missing-fields
mod = {}

storage = {
    ---@type table plain data kept for every character of the account
    account = {},
    ---@type table plain data kept for this character
    character = {},
}

log = {}
events = {}
commands = {}
filters = {}
timers = {}
ui = {}
hud = {}
ui.native = {}
render = {}
audio = {}
draw = {}
net = {}
ipc = {}
packets = {}
chat = {}
input = {}
binds = {}
timer = {}
game = {}
actions = {}
res = {}
fs = {}
json = {}
mods = {}
text = {}
client = {}
devices = {}
lobby = {}
